<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$dbn=getenv('DB_NAME')?:'sukamulya_ui_test';if($dbn!=='sukamulya_ui_test')throw new RuntimeException('Only isolated sukamulya_ui_test allowed');
$db=new mysqli('localhost','root','',$dbn);$base='http://127.0.0.1:8097/';$tag='uit'.bin2hex(random_bytes(4));$pw=bin2hex(random_bytes(20));$hash=password_hash($pw,PASSWORD_DEFAULT);
foreach(array('admin','operator','auditor') as $role){$name=$tag.'_'.$role;$s=$db->prepare('INSERT INTO admins(username,password_hash,role,is_active) VALUES(?,?,?,1)');$s->bind_param('sss',$name,$hash,$role);$s->execute();}
function verify_ui($ok,$label){if(!$ok)throw new RuntimeException($label);echo 'PASS '.$label.PHP_EOL;}
class OpsHttp{
 public $c,$html,$code,$location;public function __construct(){$this->c=curl_init();curl_setopt_array($this->c,array(CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>20,CURLOPT_PROXY=>'',CURLOPT_HEADER=>TRUE));}
 function go($path,$fields=NULL){global $base;if($fields!==NULL){$token='';foreach(curl_getinfo($this->c,CURLINFO_COOKIELIST) as $cookie){$p=explode("\t",$cookie);if(($p[5]??'')==='csrf_sukamulya_cookie')$token=$p[6];}$fields['csrf_sukamulya']=$token;curl_setopt_array($this->c,array(CURLOPT_POST=>TRUE,CURLOPT_POSTFIELDS=>http_build_query($fields)));}else curl_setopt($this->c,CURLOPT_HTTPGET,TRUE);curl_setopt($this->c,CURLOPT_URL,$base.$path);$raw=curl_exec($this->c);$size=curl_getinfo($this->c,CURLINFO_HEADER_SIZE);$head=substr($raw,0,$size);$this->html=substr($raw,$size);$this->code=curl_getinfo($this->c,CURLINFO_HTTP_CODE);$this->location=preg_match('/^Location:\s*(\S+)/mi',$head,$m)?$m[1]:'';return $this;}
 function login($role){global $tag,$pw;$this->go('admin/login');$this->go('admin/login',array('username'=>$tag.'_'.$role,'password'=>$pw));verify_ui(in_array($this->code,array(302,303,307),TRUE),'Login '.$role);return $this;}
 function post($path,$data){$this->go($path);$this->go($path,$data);verify_ui(!preg_match('/Fatal error|A PHP Error|A Database Error|Severity:/',$this->html),'POST no PHP errors '.$path);return $this;}
}
$a=(new OpsHttp())->login('admin');
$pages=array('fields'=>'admin/field-tambahan','outbox'=>'admin/antrean-email');
foreach($pages as $name=>$path){$a->go($path);verify_ui($a->code===200&&!preg_match('/Fatal error|A PHP Error|A Database Error|Severity:/',$a->html),'GET '.$path);$html=str_replace(array($tag.'_admin',ucwords(str_replace('_',' ',$tag.'_admin'))),'Admin',$a->html);file_put_contents(__DIR__.'/../tmp/family-preview/admin-'.$name.'.html',$html);}
$a->post('admin/field-tambahan',array('label'=>'Nomor rumah '.$tag,'field_type'=>'text','help_text'=>'Isi nomor rumah','citizen_editable'=>1,'sort_order'=>2));$f=$db->query("SELECT * FROM custom_field_definitions WHERE label='Nomor rumah $tag'")->fetch_assoc();verify_ui($f&&(int)$f['citizen_editable']===1,'Create editable citizen field');
$a->post('admin/field-tambahan/'.$f['id'],array('label'=>'Nomor rumah '.$tag,'field_type'=>'select','options'=>"Milik sendiri\nSewa",'is_required'=>1,'citizen_editable'=>1,'sort_order'=>3));$r=$db->query('SELECT * FROM custom_field_definitions WHERE id='.(int)$f['id'])->fetch_assoc();verify_ui($r['field_type']==='select'&&$r['options']==="Milik sendiri\nSewa",'Edit field type and options');
$before=(int)$db->query('SELECT COUNT(*) n FROM custom_field_definitions')->fetch_assoc()['n'];$a->post('admin/field-tambahan',array('label'=>'NIK warga','field_type'=>'text'));verify_ui((int)$db->query('SELECT COUNT(*) n FROM custom_field_definitions')->fetch_assoc()['n']===$before,'Sensitive field label remains rejected');
$a->post('admin/field-tambahan',array('label'=>'Opsi '.$tag,'field_type'=>'select','options'=>'Satu'));verify_ui((int)$db->query('SELECT COUNT(*) n FROM custom_field_definitions')->fetch_assoc()['n']===$before,'Choice requires at least two options');
$a->post('admin/field-tambahan',array('act'=>'toggle','field_id'=>$f['id']));verify_ui((int)$db->query('SELECT is_active FROM custom_field_definitions WHERE id='.(int)$f['id'])->fetch_assoc()['is_active']===0,'Deactivate field through existing action');
$dedupe='ui-settings-'.$tag;$email='test@example.invalid';$subject='Notifikasi uji '.$tag;$body='Pemberitahuan uji';$s=$db->prepare("INSERT INTO notification_outbox(channel,recipient,subject,body,dedupe_key,status,attempts) VALUES('email',?,?,?,?,'failed',5)");$s->bind_param('ssss',$email,$subject,$body,$dedupe);$s->execute();$oid=$db->insert_id;
$a->go('admin/antrean-email');verify_ui(strpos($a->html,$email)===FALSE&&strpos($a->html,'example.invalid')!==FALSE,'Email recipient remains masked');
$a->post('admin/antrean-email',array('act'=>'retry','outbox_id'=>$oid));$r=$db->query('SELECT * FROM notification_outbox WHERE id='.(int)$oid)->fetch_assoc();verify_ui($r['status']==='pending'&&(int)$r['attempts']===0,'Retry resets failed email to pending');
$a->post('admin/antrean-email',array('act'=>'process'));$r=$db->query('SELECT * FROM notification_outbox WHERE id='.(int)$oid)->fetch_assoc();verify_ui($r['status']==='pending'&&(int)$r['attempts']===0,'Without SMTP, process keeps email queued and sends nothing');
$o=(new OpsHttp())->login('operator');foreach($pages as $path){$o->go($path);verify_ui($o->code===403,'Operator denied '.$path);}
$g=new OpsHttp();$g->go('admin/antrean-email');verify_ui(in_array($g->code,array(302,303,307),TRUE),'Guest denied queue');
echo 'Only the isolated DB was modified; no email sent.'.PHP_EOL;
